(()=>{"use strict";document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("status"),t=document.getElementById("user-info");chrome.runtime.sendMessage({type:"GET_AUTH_TOKEN"},n=>{n&&n.token?(e&&(e.innerText="Authenticated (Ready to test)"),t&&(t.innerText=`Token length: ${n.token.length}`),e&&(e.style.color="green")):(e&&(e.innerText="Not Authenticated"),t&&(t.innerText="Please log in on the Web Dashboard."),e&&(e.style.color="red"))})})})();